// Generates src/generated/logo-data.ts from the ONE canonical logo asset.
//
// v1 stored the emblem twice: the 174 KB PNG in assets/ AND a baked base64
// copy in logo-data.cjs, both git-tracked (spec H-18). v2 keeps exactly one
// stored copy — the PNG at the repository root — and derives the data-URI
// module at build time. The generated file is gitignored so it can never go
// stale in the tree.
import { mkdir, readFile, writeFile } from 'node:fs/promises'

const logoUrl = new URL('../blazefire-logo.png', import.meta.url)
const generatedDir = new URL('../src/generated/', import.meta.url)
const outFile = new URL('logo-data.ts', generatedDir)

const png = await readFile(logoUrl)

await mkdir(generatedDir, { recursive: true })
await writeFile(
  outFile,
  `// GENERATED by scripts/generate-logo-data.mjs — do not edit.
// Source of truth: /blazefire-logo.png (${png.length} bytes)
export const LOGO_DATA_URI =
  'data:image/png;base64,${png.toString('base64')}'
`
)

console.log(`blazefire: generated logo-data.ts (${png.length} byte PNG)`)
